try (Connection c = ds.getConnection()) {
    c.setAutoCommit(false);
    long id;
    try (PreparedStatement ps = c.prepareStatement(
            "INSERT INTO party (name, kind) VALUES (?, 'person')",
            Statement.RETURN_GENERATED_KEYS)) {
        ps.setString(1, name);
        ps.executeUpdate();
        try (ResultSet k = ps.getGeneratedKeys()) { k.next(); id = k.getLong(1); }
    }
    try (PreparedStatement ps = c.prepareStatement(
            "INSERT INTO person (id, birth_date) VALUES (?, ?)")) {
        ps.setLong(1, id); ps.setObject(2, birthDate); ps.executeUpdate();
    }
    c.commit();
}
